-- =========================================================
-- INSANITY SOCIETY — contenido editable de las secciones
-- Ejecuta este archivo DESPUÉS de setup.sql:
-- Supabase > SQL Editor > New query > pegar todo > Run.
-- Se puede ejecutar más de una vez: no borra lo que ya editaste.
-- =========================================================

-- Una fila por sección: inicio, sociedad, colecciones, tienda, comunidad, general
create table if not exists public.contenido (
  clave          text primary key,
  valor          jsonb not null,
  actualizado_en timestamptz not null default now()
);

drop trigger if exists contenido_actualizado on public.contenido;
create trigger contenido_actualizado before update on public.contenido
  for each row execute function public.tocar_actualizado();

alter table public.contenido enable row level security;

drop policy if exists "contenido lectura publica" on public.contenido;
create policy "contenido lectura publica" on public.contenido
  for select to anon, authenticated using (true);

drop policy if exists "contenido admin crea" on public.contenido;
create policy "contenido admin crea" on public.contenido
  for insert to authenticated with check ((select public.is_admin()));

drop policy if exists "contenido admin edita" on public.contenido;
create policy "contenido admin edita" on public.contenido
  for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));

drop policy if exists "contenido admin borra" on public.contenido;
create policy "contenido admin borra" on public.contenido
  for delete to authenticated using ((select public.is_admin()));

grant select on public.contenido to anon, authenticated;
grant insert, update, delete on public.contenido to authenticated;

-- Textos actuales de la web (no sobrescribe lo que ya hayas editado)
insert into public.contenido (clave, valor) values
  ('inicio', $json${"titulo": "No es solo ropa.\nEs un manifiesto.", "subtitulo": "Fuerza. Disciplina. Dolor y gloria. Esto es para quienes desafían sus límites.", "boton_tienda": "Entrar a la tienda", "boton_colecciones": "Explorar colecciones", "imagen_portada": "", "franja": [{"titulo": "Envíos", "texto": "a todo Colombia"}, {"titulo": "Pedido directo", "texto": "por WhatsApp"}, {"titulo": "Algodón premium", "texto": "200 g · corte oversize"}]}$json$::jsonb),
  ('sociedad', $json${"intro": "Insanity Society no es una marca de ropa común: es una comunidad, un manifiesto y un estilo de vida. Nació en el gimnasio, entre hierro, sudor y dolor, pero su significado va más allá: representa a quienes usan el entrenamiento como un camino de transformación mental y física.", "lista_titulo": "Lo que representamos", "puntos": [{"titulo": "Fuerza mental y física", "texto": "cada prenda recuerda que entrenar no es solo estética; es disciplina, sacrificio y carácter."}, {"titulo": "Oscuridad y resiliencia", "texto": "un estilo crudo, fuerte y oscuro que transmite intensidad, dolor y gloria."}, {"titulo": "Rebeldía con propósito", "texto": "no buscamos encajar; es para quienes desafían sus límites y viven bajo sus propias reglas."}, {"titulo": "Identidad de guerreros", "texto": "no llevas solo ropa, llevas un símbolo de lo que eres y de lo que quieres llegar a ser."}], "manifiesto_titulo": "Manifiesto", "manifiesto": "Entrenamos en la oscuridad para conquistar la luz. El hierro no miente; nos forja. El dolor nos afila. Aquí no se venden prendas: se forjan símbolos. Si eliges la comodidad, no es tu lugar. Si eliges el combate, bienvenido a la Sociedad."}$json$::jsonb),
  ('colecciones', $json${"intro": "No son simples diseños. Cada colección cuenta una historia y rinde tributo a valores inquebrantables. Desde espíritus de tormenta hasta pilares que forjan la mente: esta es la esencia detrás de cada pieza.", "items": [{"nombre": "THE TRUTH BEHIND THE MASK", "jp": "", "descripcion": "La verdad detrás de la máscara. Cuatro capítulos y un epílogo sobre la batalla interior: el caos, la disciplina, la verdad y el despertar.", "destacada": true, "leyenda_titulo": "La historia", "leyenda": "«Todo guerrero libra una batalla que nadie más puede ver.» Cada prenda es un capítulo: Control vs Chaos, Untamed, Revelation, Awakening y The Path of Masks.", "enlace": "mascaras.html", "enlace_texto": "Leer la historia completa", "visible": true}, {"nombre": "DARK REBIRTH", "jp": "", "descripcion": "Estilo que impone presencia. Cortes amplios, diseños crudos. Para entrenar como leyenda y andar como si nada pudiera romperte.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "CLASSIC", "jp": "", "descripcion": "Las básicas del uniforme de guerra. Sin adornos, sin distracciones: tela dura, corte limpio y presencia pesada. Classic no es moda: es disciplina puesta en tela.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "INSANE", "jp": "", "descripcion": "No es una colección. Es una declaración. Tipografía brutal, escala exagerada y presencia que ocupa espacio. No busca gustar: busca imponer.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "BAKI-INSPIRED", "jp": "", "descripcion": "Homenaje al universo de Baki: piezas inspiradas en Baki, Jack y Yujiro. Fuerza, combate y carácter.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "REMEMBER", "jp": "", "descripcion": "Memento mori: recuerda que morirás. No como una amenaza, sino como un llamado a despertar. El ángel en la espalda simboliza la dualidad: fragilidad y fuerza, caída y renacimiento.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "VERSUS", "jp": "", "descripcion": "Reto directo: «¿Tú contra mí?». Actitud desafiante; la espalda responde sin rodeos.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "IRON", "jp": "", "descripcion": "Actitud forjada en hierro. Estética sobria centrada en la terapia del acero.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "OMEN SOCIETY", "jp": "", "descripcion": "«Bajo la mirada del cielo, levántate y hazte más fuerte». Presencia oscura y decidida.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "REDEMPTION", "jp": "", "descripcion": "El renacer a través del dolor y la disciplina. Cada repetición, cada gota de sudor y cada herida se convierten en el precio de tu redención: la fuerza.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "SUPER OVERSIZE CARGO", "jp": "", "descripcion": "Silueta amplia, caída pesada y bolsillos cargo funcionales. No es una prenda para seguir tendencias: es una prenda para imponerlas.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "JOGGERS", "jp": "", "descripcion": "Corte técnico. Actitud de batalla. Ajuste en tobillos para moverse rápido; perfectos para el hierro, la calle o los días de guerra mental.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "INSANITY ORDER", "jp": "", "descripcion": "Nueva línea de compresión. Prendas que se pegan a la piel como tu propósito: ajuste firme, secado rápido y presencia que no se olvida.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "NO MERCY", "jp": "", "descripcion": "Nueva línea de compresión. No es solo ropa: es presión controlada y poder desatado. No estás cómodo, estás concentrado.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "REBELION", "jp": "", "descripcion": "", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "BERSERK", "jp": "", "descripcion": "Furia icónica; una estética inspirada en el impulso berserker.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "CRYPT", "jp": "", "descripcion": "Camisillas con diseño gótico de líneas afiladas, en varios colores. Para entrenar ligero sin perder presencia.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "DEATH ASCENT", "jp": "", "descripcion": "Camisillas de diseño oscuro y simétrico, en varios colores. Hechas para el calor del entrenamiento y la calle.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "SENKI", "jp": "戦姫", "descripcion": "En Japón, Senki es la mujer que lucha en silencio: la que cae, se levanta y sigue. Suave por fuera, indomable por dentro. Pelea porque rendirse nunca fue una opción.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "PRIMERA EDICIÓN", "jp": "", "descripcion": "Piezas de introducción con carácter: corte y caída pensados para presencia y comodidad.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "SPORT", "jp": "", "descripcion": "Prendas de enfoque atlético: secado rápido, frescas y ligeras para moverse y rendir.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "RUNNER", "jp": "", "descripcion": "Pantaloneta clásica con bolsillos y ranuras laterales, en burda o tela semi impermeable. Opcional con licra por debajo.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "SHORT LICRA", "jp": "", "descripcion": "Minimalismo funcional: ajuste firme, cómodo y pensado para el esfuerzo.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "TOPS", "jp": "", "descripcion": "Tops en nylon de alta resistencia y elasticidad, con doble tela: cero transparencias, comodidad y estilo.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": true}, {"nombre": "KYO-KI", "jp": "狂気", "descripcion": "Significado: «locura». Energía desbordante y fuerza interior incontrolable que empuja al guerrero a superarse. «La locura no es debilidad, es el combustible de quienes no temen ir más allá».", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": false}, {"nombre": "SHOKA", "jp": "昇華", "descripcion": "The Way of Becoming: del dolor al propósito. Como el koi que desafía la cascada: resistencia, ascenso y transformación.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": false}, {"nombre": "SHUGO", "jp": "守護", "descripcion": "El Guardián. La fuerza que te sostiene cuando todo pesa: disciplina, fuego interno y una presencia que no retrocede ante sus sombras.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": false}, {"nombre": "BLOOD AND STEEL", "jp": "", "descripcion": "Declaración de guerra interna. La sangre como precio del crecimiento y el acero como voluntad inquebrantable; transformación y renacimiento.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": false}, {"nombre": "RAIJIN", "jp": "", "descripcion": "El Guerrero Rojo. Disciplina, concentración y fuerza interior; un legado que renace tras cada caída.", "destacada": true, "leyenda_titulo": "Leyenda", "leyenda": "En un cielo teñido de rojo, Raijin enfrenta sombras ancestrales hasta caer y renacer en luz carmesí. Su espíritu despierta un legado que marca a doce elegidos con el trueno del guerrero rojo. Raijin no muere; vive en todo aquel que combate y jamás se rinde.", "enlace": "raijin.html", "enlace_texto": "Leer la leyenda completa ⚡", "visible": false}, {"nombre": "RAW SOCIETY", "jp": "", "descripcion": "Crudeza de la calle y fuerza del gimnasio: una propuesta directa, sin filtros, para vivir y entrenar intensamente.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": false}, {"nombre": "STREET STRENGTH", "jp": "", "descripcion": "Fuerza nacida en la calle y liberada en el gimnasio: rebeldía, disciplina y poder real.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": false}, {"nombre": "SIXFOLD", "jp": "", "descripcion": "Seis manifestaciones del poder femenino: oscuridad, alma, protección, furia, transformación y paciencia.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": false}, {"nombre": "RIFT", "jp": "", "descripcion": "Ligereza y movilidad: diseño con aberturas laterales para entrenamiento y calle.", "destacada": false, "leyenda_titulo": "", "leyenda": "", "enlace": "", "enlace_texto": "", "visible": false}]}$json$::jsonb),
  ('tienda', $json${"intro": "Elige color, talla y agrega al carrito. Al confirmar, tu pedido llega directo a nuestro WhatsApp y te respondemos con el pago y el envío."}$json$::jsonb),
  ('comunidad', $json${"items": [{"titulo": "INSANITY POWER MEET 2025", "etiqueta": "Evento", "etiqueta_gris": false, "fecha": "21 de septiembre de 2025 · Aguazul, Casanare", "resumen": "No celebramos kilos levantados: celebramos la mente indomable forjada entre dolor, esfuerzo y disciplina. Gracias a cada atleta que dejó el alma en la tarima.", "imagen": "img/Insanity Power Meet 2025/medallas.jpg", "enlace": "power-meet-2025.html", "enlace_texto": "Ver el evento", "destacada": true, "visible": true}, {"titulo": "Fuerza base", "etiqueta": "Rutina", "etiqueta_gris": false, "fecha": "", "resumen": "Sentadilla, peso muerto y press. 5×5 con progresión lineal. Registra, come, duerme, repite.", "imagen": "", "enlace": "", "enlace_texto": "", "destacada": false, "visible": true}, {"titulo": "Dolor y gloria", "etiqueta": "Manifiesto", "etiqueta_gris": false, "fecha": "", "resumen": "El dolor es el peaje. La gloria es llegar. La Sociedad no busca aplausos: busca victorias silenciosas.", "imagen": "", "enlace": "", "enlace_texto": "", "destacada": false, "visible": true}, {"titulo": "Historias de la Sociedad", "etiqueta": "Próximamente", "etiqueta_gris": true, "fecha": "", "resumen": "Testimonios reales de transformación a base de hierro y constancia. Dolor, caída, levantarse, repetir.", "imagen": "", "enlace": "", "enlace_texto": "", "destacada": false, "visible": true}]}$json$::jsonb),
